"""
views/trust_editor_dialog.py

Manages trust level definitions — built-in (read-only) and custom (editable).

Uses a hex colour entry + live swatch preview rather than Gtk.ColorDialogButton
so it works on GTK 4.6+ (Fedora 36+) without requiring GTK 4.10.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw, Gdk, GLib

from ..backend.libvirt_manager import LibvirtManager, DEFAULT_TRUST_LEVELS


def _parse_hex(hex_color: str) -> Gdk.RGBA | None:
    """Parse a hex colour string. Returns None if invalid."""
    rgba = Gdk.RGBA()
    if rgba.parse(hex_color):
        return rgba
    return None


def _rgba_to_hex(rgba: Gdk.RGBA) -> str:
    r = int(rgba.red   * 255)
    g = int(rgba.green * 255)
    b = int(rgba.blue  * 255)
    return f"#{r:02x}{g:02x}{b:02x}"


def _draw_circle(da: Gtk.DrawingArea, cr, w: int, h: int, hex_color: str):
    """Cairo draw function — filled circle in hex_color."""
    rgba = _parse_hex(hex_color)
    if rgba is None:
        rgba = _parse_hex("#888888")
    cr.set_source_rgba(rgba.red, rgba.green, rgba.blue, 1.0)
    cr.arc(w / 2, h / 2, min(w, h) / 2, 0, 2 * 3.14159265)
    cr.fill()


def _make_swatch(size: int, hex_color: str) -> Gtk.DrawingArea:
    """Create a square DrawingArea swatch for the given colour."""
    da = Gtk.DrawingArea()
    da.set_size_request(size, size)
    da.set_valign(Gtk.Align.CENTER)
    da.set_halign(Gtk.Align.CENTER)

    def draw(widget, cr, w, h, hx=hex_color):
        _draw_circle(widget, cr, w, h, hx)

    da.set_draw_func(draw)
    return da


class TrustEditorDialog(Adw.Dialog):
    """
    Dialog listing all trust levels with add / edit / delete for custom ones.
    """

    def __init__(self, manager: LibvirtManager, parent: Gtk.Widget):
        super().__init__()
        self._mgr = manager
        self.set_title("Trust Levels")
        self.set_content_width(480)
        self.set_content_height(560)

        toolbar = Adw.ToolbarView()
        self.set_child(toolbar)

        header = Adw.HeaderBar()
        btn_add = Gtk.Button()
        btn_add.set_icon_name("list-add-symbolic")
        btn_add.set_tooltip_text("Add custom trust level")
        btn_add.connect("clicked", self._on_add)
        header.pack_end(btn_add)
        toolbar.add_top_bar(header)

        clamp = Adw.Clamp()
        clamp.set_maximum_size(440)
        clamp.set_margin_top(12)
        clamp.set_margin_bottom(12)
        clamp.set_margin_start(12)
        clamp.set_margin_end(12)

        scroll = Gtk.ScrolledWindow()
        scroll.set_policy(Gtk.PolicyType.NEVER, Gtk.PolicyType.AUTOMATIC)
        scroll.set_vexpand(True)
        scroll.set_child(clamp)
        toolbar.set_content(scroll)

        self._body = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=16)
        clamp.set_child(self._body)

        self._error_banner = Adw.Banner()
        self._error_banner.set_revealed(False)
        self._body.append(self._error_banner)

        self._builtin_group = Adw.PreferencesGroup()
        self._builtin_group.set_title("Built-in levels")
        self._builtin_group.set_description(
            "These levels ship with BulwarkOS. They cannot be deleted."
        )
        self._body.append(self._builtin_group)
        self._builtin_rows: list[Adw.ActionRow] = []

        self._custom_group = Adw.PreferencesGroup()
        self._custom_group.set_title("Custom levels")
        self._custom_group.set_description(
            "Add your own trust levels with custom colours."
        )
        self._body.append(self._custom_group)
        self._custom_rows: list[Adw.ActionRow] = []

        self._refresh()

    # ------------------------------------------------------------------ #
    # List rendering                                                       #
    # ------------------------------------------------------------------ #

    def _refresh(self):
        for row in self._builtin_rows:
            self._builtin_group.remove(row)
        self._builtin_rows.clear()

        for row in self._custom_rows:
            self._custom_group.remove(row)
        self._custom_rows.clear()

        defs = self._mgr.get_trust_defs()

        for key, defn in sorted(defs.items(), key=lambda x: x[1].get("sort", 99)):
            is_default = key in DEFAULT_TRUST_LEVELS
            row = self._make_level_row(key, defn, editable=not is_default)
            if is_default:
                self._builtin_group.add(row)
                self._builtin_rows.append(row)
            else:
                self._custom_group.add(row)
                self._custom_rows.append(row)

    def _make_level_row(self, key: str, defn: dict, editable: bool) -> Adw.ActionRow:
        row = Adw.ActionRow()
        row.set_title(defn.get("label", key))
        row.set_subtitle(key)

        color_hex = defn.get("color", "#888888")
        swatch = _make_swatch(18, color_hex)
        row.add_prefix(swatch)

        if editable:
            btn_edit = Gtk.Button()
            btn_edit.set_icon_name("document-edit-symbolic")
            btn_edit.set_tooltip_text("Edit")
            btn_edit.set_valign(Gtk.Align.CENTER)
            btn_edit.add_css_class("flat")
            btn_edit.connect("clicked", lambda _, k=key, d=dict(defn): self._on_edit(k, d))
            row.add_suffix(btn_edit)

            btn_del = Gtk.Button()
            btn_del.set_icon_name("user-trash-symbolic")
            btn_del.set_tooltip_text("Delete")
            btn_del.set_valign(Gtk.Align.CENTER)
            btn_del.add_css_class("flat")
            btn_del.add_css_class("error")
            btn_del.connect("clicked", lambda _, k=key: self._on_delete(k))
            row.add_suffix(btn_del)

        return row

    # ------------------------------------------------------------------ #
    # Add / Edit form                                                      #
    # ------------------------------------------------------------------ #

    def _on_add(self, _):
        self._show_edit_form(existing_key=None, existing_defn={})

    def _on_edit(self, key: str, defn: dict):
        self._show_edit_form(existing_key=key, existing_defn=defn)

    def _show_edit_form(self, existing_key: str | None, existing_defn: dict):
        dialog = Adw.Dialog()
        dialog.set_title("Edit trust level" if existing_key else "New trust level")
        dialog.set_content_width(400)
        dialog.set_content_height(320)

        tv = Adw.ToolbarView()
        dialog.set_child(tv)

        hdr = Adw.HeaderBar()
        btn_cancel = Gtk.Button(label="Cancel")
        btn_cancel.connect("clicked", lambda _: dialog.close())
        hdr.pack_start(btn_cancel)
        btn_save = Gtk.Button(label="Save")
        btn_save.add_css_class("suggested-action")
        hdr.pack_end(btn_save)
        tv.add_top_bar(hdr)

        clamp = Adw.Clamp()
        clamp.set_maximum_size(360)
        clamp.set_margin_top(16)
        clamp.set_margin_bottom(16)
        clamp.set_margin_start(16)
        clamp.set_margin_end(16)

        scr = Gtk.ScrolledWindow()
        scr.set_policy(Gtk.PolicyType.NEVER, Gtk.PolicyType.AUTOMATIC)
        scr.set_vexpand(True)
        scr.set_child(clamp)
        tv.set_content(scr)

        form_err = Adw.Banner()
        form_err.set_revealed(False)

        form_box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=12)
        clamp.set_child(form_box)
        form_box.append(form_err)

        grp = Adw.PreferencesGroup()
        form_box.append(grp)

        # ID row — locked when editing existing
        key_row = Adw.EntryRow()
        key_row.set_title("ID (letters, numbers, hyphens)")
        key_row.set_input_hints(Gtk.InputHints.NO_SPELLCHECK)
        if existing_key:
            key_row.set_text(existing_key)
            key_row.set_sensitive(False)
        grp.add(key_row)

        # Label row
        label_row = Adw.EntryRow()
        label_row.set_title("Display label")
        label_row.set_text(existing_defn.get("label", ""))
        grp.add(label_row)

        # Colour hex entry + live swatch preview
        color_row = Adw.ActionRow()
        color_row.set_title("Colour")
        color_row.set_subtitle("Hex value, e.g. #2aad4d")

        # Live swatch — redraws as the user types
        initial_hex = existing_defn.get("color", "#546ac1")
        preview_swatch = _make_swatch(24, initial_hex)

        hex_entry = Gtk.Entry()
        hex_entry.set_text(initial_hex)
        hex_entry.set_max_length(7)
        hex_entry.set_width_chars(8)
        hex_entry.set_valign(Gtk.Align.CENTER)
        hex_entry.add_css_class("monospace")
        hex_entry.get_style_context().add_class("flat")

        # Current colour state — updated on every keystroke
        current_color = [initial_hex]

        def on_hex_changed(entry):
            text = entry.get_text().strip()
            if not text.startswith("#"):
                text = "#" + text
            if _parse_hex(text) is not None:
                current_color[0] = text
                hex_entry.remove_css_class("error")
                # Redraw swatch with new colour
                def draw_live(da, cr, w, h, hx=text):
                    _draw_circle(da, cr, w, h, hx)
                preview_swatch.set_draw_func(draw_live)
                preview_swatch.queue_draw()
            else:
                hex_entry.add_css_class("error")

        hex_entry.connect("changed", on_hex_changed)

        suffix_box = Gtk.Box(spacing=8)
        suffix_box.set_valign(Gtk.Align.CENTER)
        suffix_box.append(hex_entry)
        suffix_box.append(preview_swatch)
        color_row.add_suffix(suffix_box)
        grp.add(color_row)

        def on_save(_btn):
            raw_key   = existing_key or key_row.get_text().strip().lower()
            # Sanitise: only keep alphanumeric, hyphens, underscores
            safe_key  = "".join(c for c in raw_key if c.isalnum() or c in "-_")
            lbl       = label_row.get_text().strip()
            color     = current_color[0]

            if not safe_key:
                form_err.set_title("ID cannot be empty.")
                form_err.set_revealed(True)
                return
            if not lbl:
                form_err.set_title("Display label cannot be empty.")
                form_err.set_revealed(True)
                return
            if _parse_hex(color) is None:
                form_err.set_title("Invalid hex colour.")
                form_err.set_revealed(True)
                return

            ok, msg = self._mgr.save_custom_trust_level(safe_key, lbl, color)
            if ok:
                dialog.close()
                self._refresh()
            else:
                form_err.set_title(msg)
                form_err.set_revealed(True)

        btn_save.connect("clicked", on_save)
        dialog.present(self)

    # ------------------------------------------------------------------ #
    # Delete                                                               #
    # ------------------------------------------------------------------ #

    def _on_delete(self, key: str):
        confirm = Adw.MessageDialog(
            transient_for=self.get_root(),
            heading="Delete trust level?",
            body=f"'{key}' will be removed. VMs using it will show as Unknown.",
        )
        confirm.add_response("cancel", "Cancel")
        confirm.add_response("delete", "Delete")
        confirm.set_response_appearance("delete", Adw.ResponseAppearance.DESTRUCTIVE)

        def on_response(d, r):
            if r == "delete":
                ok, msg = self._mgr.delete_custom_trust_level(key)
                if ok:
                    self._refresh()
                else:
                    self._error_banner.set_title(msg)
                    self._error_banner.set_revealed(True)

        confirm.connect("response", on_response)
        confirm.present()
